     "stem":"尽管寄主并没有针对寄生植物进化出特别的反抗手段，但这并不代表寄主会对寄生植物 。人们已经发现，寄主某些偶然进化出的特性（抗性反应）竟能有效抵御寄生植物的寄生行为。例如，菟丝子可以寄生在野生番茄上，却不能寄生在栽培番茄上。存在天然抗性的这些物种为人们防治寄生植物提供了宝贵的遗传资源。 填入画横线部分最恰当的一项是：",
