     "isAnswer":true,
     "explain":"根据横线后文可知，传统作业管理中存在“眼中有作业、有分数，但唯独没有人”的痼疾，而横线前文强调布置作业是为了育人。故横线处表达之前的作业管理中存在把育人与作业、分数的地位弄颠倒了的现象，B项“本末倒置”比喻把主要的和次要的、本质和非本质的关系弄颠倒了，符合文意，当选。 A项“揠苗助长”比喻违反事物的发展规律，急于求成，反而坏事，文段未体现“违反事物的发展规律”，与文意不符，排除；C项“缘木求鱼”比喻行事方向、方法不对，一定达不到目的，D项“徒有其表”指空有其外表，不实在，均无法体现出“颠倒”的含义，与文意不符，排除。 故正确答案为B。 【文段出处】光明网《作业改革应回到育人原点》",
