     "answer":"B",
     "isAnswer":true,
     "explain":"横线前介绍了两种不同的空间碎片清除方案，横线后介绍两类清除方式都是让碎片离开当前轨道并进入大气层烧毁，即最后实现的目标一致，故横线处表达虽然方法不同但最终实现的目标相同。B项“殊途同归”比喻采取不同的方法而得到相同的结果，符合文意，当选。 A项“如出一辙”指好像出自同一车辙，形容两种事物非常相似，侧重强调两种清除方式“相似”，与文意不符，排除；C项“双管齐下”比喻从两方面同时进行，D项“各有千秋”指各有所长，各有优点，各有特色，与B项相比，均无法体现文段中得到了相同结果这一含义，与文意不符，排除。 故正确答案为B。 【文段出处】人民网《太空也需要“清道夫”（科技大观）》",
