     "answer":"C",
     "isAnswer":true,
     "explain":"根据“，”可知，横线处所填成语与“抓早抓小”语义相近，且根据前文“祸几始作，当杜其萌；疾证方形，当绝其根”，即杜绝祸患当于其萌发之时，斩断病根当于其形成之际可知，应体现在问题刚萌发的时候尽早发现制止，避免问题扩大，产生重大风险之意。C项“见微知著”指见到细微的苗头，就能预知事物发展的方向，符合文意，当选。 A项“对症下药”意思是针对病症开方用药，B项“审时度势”指观察分析时势，估计情况的变化，侧重于对时势的估量，D项“当机立断”形容抓住时机、立刻决断，均无法体现在问题萌发阶段及早发现之意，排除。 故正确答案为C。 【文段出处】新华社《〈求是〉杂志发表习近平总书记重要文章〈正确认识和把握我国发展重大理论和实践问题〉》",
