     "answer":"B",
     "isAnswer":true,
     "explain":"根据“先上线后治理的情况十分普遍”可知，横线处应表达互联网公司上线新技术或产品前明知存在风险或隐患却不管不顾的态度，B项“视而不见”表示不关心，不重视，不注意或假装没看见，符合文意，当选。 A项“束手无策”形容处于一筹莫展的困境，遇到问题没有解决的办法，C项“一无所知”指什么都不知道，后文指出“先上线后治理”说明互联网公司了解情况并有解决办法，均与文意相悖，排除；D项“含糊其辞”指故意把话说得含含糊糊、不清楚，与文意无关，排除。 故正确答案为B。 【文段出处】中国青年报《套路贷“中转站” 售假者“新天地”——小程序乱象待整治》",
