     "answer":"C",
     "isAnswer":true,
     "explain":"根据后文可知，下调网约车平台抽成比例虽会使平台单笔订单的抽成减少，但有助于给司机减负，也会促进平台自身的良性发展，强化规模效应，故抽成减少是双赢之举。横线前出现“不是”，故横线处所填成语与后文语义相反，需表达下调网约车平台抽成比例仅对一方有好处，C项“零和博弈”指参与博弈的各方，在严格竞争下，一方的收益必然意味着另一方的损失，博弈各方的收益和损失相加总和永远为“零”，双方不存在合作的可能，符合文意，当选。 A项“拔苗助长”比喻违反事物发展的客观规律，急于求成反而坏事，文段未体现“违反事物的发展规律”，与文意不符，排除； B项“空头支票”指不能兑现，取不到钱的支票，比喻不准备实现的诺言，与文意不符，排除； D项“双赢游戏”指双方都能得益的游戏，与文意相悖，排除。 故正确答案为C。 【文段出处】澎湃新闻《【社论】下调抽成比例：多方共赢才能长远》",
