     "stem":"我们取得的历史性成就、发生的历史性变革，在人类历史长河中是不多见的。这些实实在在的进步，让每一个中国人都倍感荣光，让唱衰中国的歪理邪说 ，也让越来越多的国际有识之士为我们点赞。",
