     "stem":"随着技术经验积累，高空风弹道修正等技术方法能使火箭在飞行过程中有效抵抗风干扰。为了有更强的适应性，本发长八火箭在使用自主抗干扰控制技术等成熟方法之外，还增加了自动滚转减载技术，根据风的来向，会在空中主动滚动调整，使火箭用更稳定的优势面来应对高空风，用“ ”的方式，通过自身的旋转抵消掉高空风的影响。 填入画横线部分最恰当的一项是：",
