     "answer":"A",
     "isAnswer":false,
     "explain":"根据文意可知，横线处所填成语需表达传播者应对“中国故事”及“西方媒体的运行规则”比较了解、熟悉的意思。A项“知己知彼”指对自己和对方的情况都了解得很透彻，“知己”可以体现传播者对中国故事的熟悉，“知彼”可以体现传播者了解西方媒体的运行规则，符合文意，当选。 B项“别出心裁”意思是另有一种构思或设计，指想出的办法与众不同；D项“兼收并蓄”指把不同内容、不同性质的东西吸收并保存起来。二者均没有体现熟悉、了解的意思，与文意不符，排除。 C项：“胸有成竹”比喻做事之前已有成熟的计划或做事很有把握，与文意不符，排除。 故正确答案为A。 【文段出处】甘肃社会科学2020年第5期《跨文化传播中的话语力问题》",
