     "answer":"D",
     "isAnswer":false,
     "explain":"横线处搭配“线索摸排”且根据“在技术的赋能下，检察机关在办理公益诉讼案件时如同拥有了顺风耳、千里眼”以及横线前“能有效避免”可知，横线处与“顺风耳”“千里眼”所代表的高效、精准形成反义并列，应体现技术赋能前线索摸排的艰难和低效之意，D项“大海捞针”指在大海里捞一根针，比喻极难找到，符合文意，当选。 A项“刻舟求剑”比喻办事刻板拘泥，不知根据实际情况处理问题，文段并非强调方法刻板，而是强调线索寻找过程的艰难，与文意不符，排除；B项“管中窥豹”指所见不全面，仅能体现线索摸排的不全面，不及D项还能体现出该项工作的困难，排除；C项“缘木求鱼”指爬到树上去找鱼，比喻方向或方法不对，不可能达到目的，与文意不符，排除。 故正确答案为D。 【文段出处】法治日报《技术赋能让公益诉讼提质增效》",
