     "stem":"下调网约车平台抽成比例并不是“ ”。对平台来说，每一单的抽成少了，但给司机切实减负了，司机更有动力去改善服务，打车成本降低，服务质量提升，会吸引更多乘客选择平台出行，强化规模效应。 填入画横线部分最恰当的一项是：",
