     "stem":"红树林的地下部分长期处于厌氧环境，减缓了根系和凋落物的分解速率，加速了碳埋藏速率。此外，红树林大多分布于沉积型海岸河口，由上游河流和海洋潮汐共同作用带来的大量外源性碳，被它们固定并快速沉积下来。这“ ”的组合拳使得红树林成为海岸带蓝碳碳汇的主要贡献者。 填入画横线部分最恰当的一项是：",
