     "stem":"明代《群芳谱》记载：“剪秋罗，一名汉宫秋。色深红，花瓣分数岐，尖峭可爱。八月间开。”剪秋罗有五片花瓣，每片都分为两叉，每个分叉侧沿还有一细小的丝带状分叉———像是被裁剪而成，又在秋季开花，故此得名。剪秋罗花色大红，明清两代文人常把它比作瑶池仙子之霞帔、织女织出的天衣，或是虞姬诀别楚霸王时的舞裙，总之与女子的衣裳相关。不过剪秋罗终究只是草本花卉，开不长久，深秋之后渐渐枯死。所以它在明代虽被当做名花，却是末流。明朝人编写过一部《瓶花谱》，选的都是适宜剪来插在瓶里的花卉，剪秋罗位列“九品一命”，是插花里的最下品。晚清诗人黄燮清也曾用剪秋罗入诗词：“猩痕点点雨中看，认是西风残泪湿齐纨。”用秋季凄风苦雨中的剪秋罗花，来寄托悲秋情绪。 关于“剪秋罗”，上文中没有提到的是（ ）。",
