     "stem":"推进公交专用车道的开放共享，不等于废除公交专用通道，更不等于在城市交通治理中不再坚持“公交先行”的理念。理想状况下的公交专用通道共享，应该是在不影响公交通行效率的前提下，方便社会车辆的通行，从而在整体上提升道路交通的通行效率，而并非 。 填入画横线部分最恰当的一项是：",
