     "stem":"制止网络暴力，加强、完善相关制度性建设刻不容缓。 ，每一个口出恶言之人都是推动网暴潮水前进的一部分。反过来讲，在评判热点人物和事件时保持善意和理智，哪怕只是做到少说不说，这样的人每多一个，抵御网暴的堤坝就能高一分。 填入画横线部分最恰当的一项是：",
