     "answer":"D",
     "isAnswer":false,
     "explain":"横线处所填词语搭配“发展路径”。根据“完全融入了中国古典木构建筑技术的主流······形成此后中国官式建筑······的发展路径”可知，横线处应体现此后中国官式建筑按照这一路径继续发展之意。D项“一以贯之”指用一种思想理论贯穿于始终，置于此处可体现发展路径一直延续之意，符合文意，当选。A项“源远流长”比喻历史悠久，根底深厚，常搭配“历史”，与“发展路径”搭配不当，排除。B项“标新立异”多形容敢于改革创新或提出新奇的主张，表示与一般不同，也指为了显示自己而故意另搞一套，文段既未体现“创新”，也未体现“故意另搞一套”，不符合文意，排除。C项“一枝独秀”形容在同类人或同类事物中出类拔萃，文段并未体现“出类拔萃”之意，不符合文意，排除。 故正确答案为D。 【文段出处】吴文化博物馆《百工有业｜从紫禁之巅到纽约苏园——从古代走入现代的香山帮》",
