     "stem":"氦 ，在地球上，它的主要存在形式是单独离散的氦原子，即氦气，几乎不与任何元素发生化学反应。氦气轻盈飘逸，它的密度很小，是除了氢气以外密度最小的物质。 填入画横线部分最恰当的一项是：",
