     "answer":"C",
     "isAnswer":false,
     "explain":"根据“它的主要存在形式是单独离散的氦原子”以及“几乎不与任何元素发生化学反应”可知，氦具有单独存在，不与其他元素发生反应的特性。C项“独来独往”指独身来往，不与其他人为伍，符合文意，当选。A项“独善其身”指怕招惹是非，只顾自己好，不关心身外之事，文段未提及只顾自己，不管别人之意，排除；B项“独树一帜”指独自打起一面旗号，比喻与众不同，自成一格，文段并未对比氦与其他元素的不同，排除；D项“独一无二”形容唯一的，难得的，没有相同或可以相比的，文段未提及氦的唯一性，排除。 故正确答案为C。 【文段出处】知乎《元素的故事：嗨，氦！》",
