     "answer":"C",
     "isAnswer":false,
     "explain":"根据“既不······也不······”可知，横线处成语与“妄自尊大”语义相反，应体现出过分看轻自己之意，C项“妄自菲薄”指毫无根据地过分看轻自己，符合文意，当选。 A项“固步自封”比喻守着老一套，不求进步，反义应为“革故鼎新”等，D项“甘居人后”指愿意处于落后的地位，不求上进，反义应为“奋勇争先”等，均无法与“妄自尊大”构成反义并列，排除；B项“骄傲自满”指自高自大、满足于已有的成绩，与“妄自尊大”语义相近，无法构成反义并列，排除。 故正确答案为C。 【文段出处】《习近平：在中国科学院第十九次院士大会、中国工程院第十四次院士大会上的讲话》",
