     "explain":"根据横线前转折关联词“但”可知，横线处所填成语应与前文语义相反，且根据横线后“寄主某些偶然进化出的特性（抗性反应）竟能有效抵御寄生植物的寄生行为”可知，横线处句子应表达寄主不会对寄生植物放任不管的意思。A项“听之任之”指任凭事物存在发展而不去过问，符合文意，当选。 B项“退避三舍”比喻对人让步，避免冲突，文段并未体现寄主有主动退让的行为，与文意不符，排除； C项“熟视无睹”指对某一事物漠不关心，侧重态度上的忽视，与后文“抗性反应抵御寄生行为”的文意不符，排除； D项“却之不恭”指对别人的邀请、赠与等，如果拒绝接受，就显得不恭敬，与文段语境无关，排除。 故正确答案为A。 【文段出处】知网《奇特的寄生植物》",
