     "explain":"“对敌方的军事行动······对敌方的结构体系”为句式一致引导的并列，故横线处成语应与“心知肚明”语义相近，体现出对敌方的军事行动非常了解之意。A项“洞若观火”指清楚得就像看火一样，形容观察事物透彻分明，符合文意，当选。 B项“防患未然”指在祸患发生之前就加以预防，强调“预防”，C项“胸有成竹”比喻处理事情之前已有完整的谋划打算，强调“有把握”，D项“未卜先知”指没有占卜便能事先知道，强调“预见性”，均无法体现清楚了解之意，排除。 故正确答案为A。 【文段出处】解放军报《善疑者善谋》",
