     "explain":"横线处与“锲而不舍”构成近义并列，应体现出要坚持之意。D项“久久为功”意为要持之以恒，锲而不舍，驰而不息，符合文意，当选。A项“点石成金”比喻修改文章时稍稍改动原来的文字，就使它变得很出色，C项“风雨无阻”比喻无论发生什么情况，都按照原计划行事，二者均无法体现坚持之意，排除；B项“水滴石穿”比喻力量虽小，只要坚持不懈，事情就能成功，词语本身既包含了坚持的行为，也包含了坚持带来的结果，而横线处与“锲而不舍”并列，仅需体现坚持之意，未包含坚持之后带来的结果，与文意不符，排除。 故正确答案为D。 【文段出处】党建网《学习语｜推动经济社会发展全面绿色转型》",
